// Selected official UIParticleFlipFix; generated by prepare_activity_battle_rank_ui.py.
using Zjcs.Official.WorldUI;
using Zjcs.Official.ProfessionUI;
using Zjcs.Official.TeamUI;
namespace Zjcs.Official.ActivityRankUI
{
using System;
using Object = UnityEngine.Object;
using System.Collections.Generic;
using UnityEngine;

[ExecuteAlways]
public class UIParticleFlipFix : MonoBehaviour
{
	[Serializable]
	private struct ParticleFlip
	{
		public Transform Flip1;

		public Transform Flip2;
	}

	[SerializeField]
	private List<ParticleFlip> mFlips;

	public bool IsEmpty
	{
		get
		{
			if (mFlips != null)
			{
				return mFlips.Count == 0;
			}
			return true;
		}
	}

	private void OnEnable()
	{
		Update();
	}

	private void Update()
	{














		if (mFlips == null || mFlips.Count == 0)
		{
			return;
		}
		Vector3 lossyScale = ((Component)this).transform.lossyScale;
		bool flag = lossyScale.x < 0f;
		bool flag2 = lossyScale.y < 0f;
		int i = 0;
		for (int count = mFlips.Count; i < count; i++)
		{
			ParticleFlip particleFlip = mFlips[i];
			if (!((Object)(object)particleFlip.Flip2 == (Object)null) && !((Object)(object)particleFlip.Flip1 == (Object)null))
			{
				Vector3 localScale = particleFlip.Flip1.localScale;
				if (localScale.x < 0f != flag)
				{
					localScale.x *= -1f;
					particleFlip.Flip1.localScale = localScale;
				}
				else if (localScale.y < 0f != flag2)
				{
					localScale.y *= -1f;
					particleFlip.Flip1.localScale = localScale;
				}
				Vector3 localScale2 = particleFlip.Flip2.localScale;
				if (localScale2.x < 0f != flag)
				{
					localScale2.x *= -1f;
					particleFlip.Flip2.localScale = localScale2;
				}
				else if (localScale2.y < 0f != flag2)
				{
					localScale2.y *= -1f;
					particleFlip.Flip2.localScale = localScale2;
				}
			}
		}
	}
}
}
